<?php
namespace App\Http\Controllers\HR;use App\Http\Controllers\Controller;use App\Models\{Employee,PerformanceReview};use Illuminate\Http\Request;class PerformanceController extends Controller{public function index(){ $p=auth()->user()->property_id;return view('hr.performance',['reviews'=>PerformanceReview::with('employee')->where('property_id',$p)->latest('review_date')->paginate(25),'employees'=>Employee::where('property_id',$p)->where('status','active')->get()]);}public function store(Request $r){$p=auth()->user()->property_id;$d=$r->validate(['employee_id'=>'required|integer','review_date'=>'required|date','overall_score'=>'required|numeric|min:0|max:100','strengths'=>'nullable|max:3000','improvement_areas'=>'nullable|max:3000','goals'=>'nullable|max:3000']);PerformanceReview::create($d+['property_id'=>$p,'reviewer_id'=>auth()->id(),'status'=>'completed']);return back()->with('success','Performance review recorded.');}}